if(isset($_GET['errors'])&&isset($_SESSION['bulk_import'])){header('Content-Type:text/csv');header('Content-Disposition:attachment; filename="import-errors.csv"');$out=fopen('php://output','w');fputcsv($out,['Excel Row','Item Code','Product Name','Errors','Warnings']);foreach($_SESSION['bulk_import']['rows'] as $r)if($r['_status']!=='valid')fputcsv($out,[$r['_row'],$r['Item Code'],$r['Product Name'],implode('; ',$r['_errors']),implode('; ',$r['_warnings'])]);fclose($out);exit;}
