if($_SERVER['REQUEST_METHOD']==='POST'&&isset($_POST['confirm'])){verify_csrf();$batch=$_SESSION['bulk_import']??null;if(!$batch)redirect('bulk_import.php');$errors=array_filter($batch['rows'],fn($r)=>$r['_status']==='error');if($errors){flash('danger','Fix the red error rows before importing.');redirect('bulk_import.php');}$db->beginTransaction();try{$grouped=[];foreach($batch['rows'] as $r)$grouped[$r['Supplier Code'].'|'.$r['Supplier Invoice'].'|'.$r['Purchase Date']][]=$r;$purchases=0;foreach($grouped as $group){$first=$group[0];$s=$db->prepare('SELECT id FROM suppliers WHERE supplier_code=? FOR UPDATE');$s->execute([$first['Supplier Code']]);$supplierId=$s->fetchColumn();if(!$supplierId){$db->prepare('INSERT INTO suppliers(supplier_code,name,phone) VALUES(?,?,?)')->execute([$first['Supplier Code'],$first['Supplier Name'],$first['Supplier Phone']]);$supplierId=(int)$db->lastInsertId();}$lines=[];foreach($group as $r){$cat=$db->prepare('SELECT id FROM categories WHERE LOWER(name)=LOWER(?)');$cat->execute([$r['Category']]);$catId=$cat->fetchColumn();if(!$catId){$db->prepare('INSERT INTO categories(name) VALUES(?)')->execute([$r['Category']]);$catId=(int)$db->lastInsertId();}$brand=$db->prepare('SELECT id FROM brands WHERE LOWER(name)=LOWER(?)');$brand->execute([$r['Brand']]);$brandId=$brand->fetchColumn();if(!$brandId){$db->prepare('INSERT INTO brands(name) VALUES(?)')->execute([$r['Brand']]);$brandId=(int)$db->lastInsertId();}$p=$db->prepare('SELECT id FROM products WHERE item_code=?');$p->execute([$r['Item Code']]);$productId=$p->fetchColumn();if(!$productId){$db->prepare('INSERT INTO products(item_code,name,barcode,brand_id,category_id,unit,retail_price,wholesale_price,current_stock,avg_cost,serial_tracking) VALUES(?,?,?,?,?,?,?,?,0,0,?)')->execute([$r['Item Code'],$r['Product Name'],$r['Barcode']?:null,$brandId,$catId,$r['Unit'],$r['Retail Price'],$r['Wholesale Price'],$r['Serial Number']!==''?1:0]);$productId=(int)$db->lastInsertId();}$lines[]=['product_id'=>(int)$productId,'quantity'=>(float)$r['Purchase Quantity'],'unit_cost'=>(float)$r['Cost Price'],'retail_price'=>(float)$r['Retail Price'],'wholesale_price'=>(float)$r['Wholesale Price'],'update_prices'=>isset($_POST['update_prices']),'serials'=>$r['Serial Number']!==''?[$r['Serial Number']]:[]];}post_purchase($db,['supplier_id'=>$supplierId,'supplier_invoice'=>$first['Supplier Invoice'],'purchase_date'=>$first['Purchase Date'],'discount'=>0,'tax'=>0,'paid_amount'=>(float)($_POST['paid_amount']??0),'due_date'=>$_POST['due_date']??'','payment_method'=>$_POST['payment_method']??'cash','notes'=>'Created by Excel bulk import'], $lines);$purchases++;}$counts=array_count_values(array_column($batch['rows'],'_status'));$db->prepare('INSERT INTO import_batches(filename,status,valid_rows,warning_rows,error_rows,options,imported_by,posted_at) VALUES(?,"posted",?,?,?,?,?,NOW())')->execute([$batch['filename'],$counts['valid']??0,$counts['warning']??0,$counts['error']??0,json_encode(['update_prices'=>isset($_POST['update_prices']),'purchase_count'=>$purchases]),user()['id']]);$batchId=(int)$db->lastInsertId();$rowInsert=$db->prepare('INSERT INTO import_batch_rows(batch_id,excel_row,supplier_code,supplier_name,supplier_phone,supplier_invoice,purchase_date,item_code,product_name,barcode,serial_number,brand,unit,category,cost_price,retail_price,wholesale_price,purchase_quantity,validation_status,messages,raw_data) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)');foreach($batch['rows'] as $sourceRow){$rowInsert->execute([$batchId,$sourceRow['_row'],$sourceRow['Supplier Code'],$sourceRow['Supplier Name'],$sourceRow['Supplier Phone'],$sourceRow['Supplier Invoice'],$sourceRow['Purchase Date'],$sourceRow['Item Code'],$sourceRow['Product Name'],$sourceRow['Barcode']?:null,$sourceRow['Serial Number']?:null,$sourceRow['Brand'],$sourceRow['Unit'],$sourceRow['Category'],$sourceRow['Cost Price'],$sourceRow['Retail Price'],$sourceRow['Wholesale Price'],$sourceRow['Purchase Quantity'],$sourceRow['_status'],implode('; ',array_merge($sourceRow['_errors'],$sourceRow['_warnings'])),json_encode($sourceRow)]);}audit($db,'post','excel_import',$batchId,null,['filename'=>$batch['filename'],'rows'=>count($batch['rows'])]);$db->commit();unset($_SESSION['bulk_import']);flash('success',"Excel import completed. $purchases purchase invoice(s) posted and stock increased.");redirect('purchases.php');}catch(Throwable $e){$db->rollBack();flash('danger','Nothing was imported. '.$e->getMessage());redirect('bulk_import.php');}}
$batch=$_SESSION['bulk_import']??null;$counts=$batch?array_count_values(array_column($batch['rows'],'_status')):[];page_start('Excel Bulk Add','bulk_import.php');?>
